/// 🪙️ Withholds the real current-call protocol allowance before entering producer work.
pub fn with_core_wire_reserve<R:Copy>(cx:&mut StepContext<'_>,header:usize,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->Result<R,OriginalTurnFailure>{let demand=semio_framework_job_return_escrow_publication::OriginalEscrowPublisher::core_wire_reserve(header)?;let grant=cx.retained_grant();let fuel=cx.fuel_remaining();if grant.maximum_items<demand.items||grant.maximum_copy_bytes<demand.copy_bytes||grant.maximum_depth==0{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"Core wire reserve absent").into())}if fuel<demand.work{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Core wire work absent").into())}let narrowed=RetainedCloneGrant{maximum_items:grant.maximum_items-demand.items,maximum_copy_bytes:grant.maximum_copy_bytes-demand.copy_bytes,..grant};let deadline=cx.deadline_us();cx.with_retained_loan(narrowed,|cx|cx.with_original_work_loan(fuel-demand.work,deadline,run))}
