 pub fn admit_step(&mut self,input:RetainedTurnInput,budget:StepBudget,clock:fn()->Option<u64>)->OriginalActorCall<OriginalActorAdmission,AdmissionFailure>{if self.has_close_failure()||self.fault.is_some()||self.retirement.is_some()||self.value_fault.is_some()||self.value_retirement.is_some(){return OriginalActorCall{input,receipt_spent:Default::default(),work_units_spent:0,result:Err(refusal("original guest failure remains in paid custody").into())}}self.context.admit_step(input,budget,clock)}
 /// 🌱️ Registers original UI backing before the component bundle can create values.
 pub fn admit_plugin_step(&mut self,budget:semio_framework_actor::OriginalJobBudget,clock:fn()->Option<u64>,ensure:impl FnOnce(&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->OriginalActorCall<OriginalActorAdmission,AdmissionFailure>{
  let input=budget.input;let policy=budget.retained_policy;
  if let Err(error)=Self::plugin_budget(budget){return OriginalActorCall{input,receipt_spent:Default::default(),work_units_spent:0,result:Err(error.into())}}
  if budget.cancelled{return OriginalActorCall{input,receipt_spent:Default::default(),work_units_spent:0,result:Err(ValueError::literal(ValueRefusalKind::Canceled,"original plugin admission cancelled").into())}}
  if budget.fuel==0||clock().is_none_or(|now|now>=budget.deadline_us){return OriginalActorCall{input,receipt_spent:Default::default(),work_units_spent:0,result:Ok(OriginalActorAdmission{ready:false,progress:Default::default()})}}
  if !self.context.is_ready(){let mut call=self.admit_step(input,budget.step_budget(),clock);if let Ok(admission)=call.result.as_mut(){admission.ready=false;}return call}
  if self.has_close_failure()||self.fault.is_some()||self.retirement.is_some()||self.value_fault.is_some()||self.value_retirement.is_some(){return OriginalActorCall{input,receipt_spent:Default::default(),work_units_spent:0,result:Err(refusal("plugin bootstrap retains its original failed owner").into())}}
  let ui=&mut self.ui_arena;let mut spent=RetainedCloneProgress::default();let call=self.context.dispatch_step(input,budget.step_budget(),&mut spent,clock,|cx|->Result<bool,OriginalTurnFailure>{
   if !cx.admit_original_core_wire_delivery()?{return Ok(false)}if !cx.admit_original_return_table()?{return Ok(false)}if !cx.admit_original_escrow_publisher()?{return Ok(false)}
   while !ui.ready(){let before=(cx.retained_progress(),cx.fuel_remaining());if ui.advance(cx)?{break}if cx.should_yield()||cx.is_cancelled()||before==(cx.retained_progress(),cx.fuel_remaining()){return Ok(false)}}
   if cx.should_yield()||cx.is_cancelled(){return Ok(false)}ensure(cx)?;Ok(true)
  });let result=match call.result{Ok(ready)=>Ok(OriginalActorAdmission{ready,progress:call.receipt_spent}),Err(OriginalActorCallError::Authority(error))=>Err(error.into()),Err(OriginalActorCallError::Semantic(error))=>{*self.value_fault=Some(error);Err(refusal("original plugin UI admission retains its failed Source").with_retained_progress(call.receipt_spent).into())}};OriginalActorCall{input:call.input,receipt_spent:call.receipt_spent,work_units_spent:call.work_units_spent,result}
 }
 fn plugin_budget(budget:semio_framework_actor::OriginalJobBudget)->Result<(),ValueError>{budget.input.validate()?;let grant=budget.input.grant;let policy=budget.retained_policy;if budget.fuel>budget.input.work.fuel||budget.deadline_us>budget.input.work.absolute_deadline_us||policy.maximum_items>grant.maximum_items||policy.maximum_copy_bytes>grant.maximum_copy_bytes||policy.maximum_capacity_bytes>grant.maximum_capacity_bytes||policy.maximum_release_bytes>grant.maximum_release_bytes||policy.maximum_depth>grant.maximum_depth{return Err(refusal("original plugin scope exceeds its unified source currency"))}Ok(())}
